<?php
declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/_helper.php';perpus_require_access();$manage=perpus_can_manage();$id=(int)($_GET['id']??$_POST['id']??0);$error='';$flash=perpus_flash();
if($_SERVER['REQUEST_METHOD']==='POST'&&$manage){require_valid_csrf();$action=$_POST['action']??'save';if($action==='delete'){$st=$pdo->prepare("SELECT COUNT(*) FROM perpustakaan_buku WHERE kategori_id=?");$st->execute([$id]);if((int)$st->fetchColumn()>0)$error='Kategori masih digunakan oleh buku dan tidak dapat dihapus.';else{$pdo->prepare('DELETE FROM perpustakaan_kategori WHERE id=?')->execute([$id]);perpus_audit($pdo,'DELETE',$id,'Menghapus kategori perpustakaan');perpus_flash('Kategori berhasil dihapus.');redirect('perpustakaan/kategori.php');}}else{$kode=trim((string)($_POST['kode']??''));$nama=trim((string)($_POST['nama']??''));$aktif=(int)($_POST['aktif']??1);$ket=trim((string)($_POST['keterangan']??''));if($kode===''||$nama==='')$error='Kode dan nama wajib diisi.';else{try{if($id>0){$pdo->prepare('UPDATE perpustakaan_kategori SET kode=?,nama=?,aktif=?,keterangan=? WHERE id=?')->execute([$kode,$nama,$aktif,$ket,$id]);perpus_audit($pdo,'UPDATE',$id,'Mengubah kategori perpustakaan');perpus_flash('Kategori diperbarui.');}else{$st=$pdo->prepare('INSERT INTO perpustakaan_kategori(kode,nama,aktif,keterangan) VALUES(?,?,?,?)');$st->execute([$kode,$nama,$aktif,$ket]);$new=(int)$pdo->lastInsertId();perpus_audit($pdo,'CREATE',$new,'Menambah kategori perpustakaan');perpus_flash('Kategori ditambahkan.');}redirect('perpustakaan/kategori.php');}catch(PDOException $e){$error='Kode atau nama kategori sudah digunakan.';}}}}
$q=trim((string)($_GET['q']??''));$where=[];$params=[];if($q!==''){$where[]='(kode LIKE ? OR nama LIKE ?)';$like="%$q%";$params=[$like,$like];}$sql='SELECT * FROM perpustakaan_kategori'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY nama';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$current=$id?null:['kode'=>'','nama'=>'','aktif'=>1,'keterangan'=>''];if($id){$st=$pdo->prepare('SELECT * FROM perpustakaan_kategori WHERE id=?');$st->execute([$id]);$current=$st->fetch();if(!$current)exit('Kategori tidak ditemukan.');}
$page_title='Kategori Perpustakaan';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?><main class="main perpus-page"><header class="topbar"><div class="topbar-title">Kategori Perpustakaan</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1><i class="bi bi-tags-fill"></i> Kategori Buku</h1><p>Kelola kategori buku perpustakaan.</p></div><a class="btn btn-secondary" href="<?=BASE_URL?>perpustakaan/index.php"><i class="bi bi-arrow-left"></i> Kembali</a></div><?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="form-card"><form method="get" class="form-grid"><div class="form-group"><label>Cari</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Kode atau nama kategori"></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-search"></i> Cari</button></div></form></div><?php if($manage):?><div class="form-card"><h5><?= $id?'Edit':'Tambah' ?> Kategori</h5><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="form-group"><label>Kode *</label><input class="form-control" name="kode" required value="<?=e($current['kode'])?>"></div><div class="form-group"><label>Nama *</label><input class="form-control" name="nama" required value="<?=e($current['nama'])?>"></div><div class="form-group"><label>Status</label><select class="form-control" name="aktif"><option value="1" <?=$current['aktif']?'selected':''?>>Aktif</option><option value="0" <?=!$current['aktif']?'selected':''?>>Nonaktif</option></select></div><div class="form-group"><label>Keterangan</label><input class="form-control" name="keterangan" value="<?=e($current['keterangan']??'')?>"></div></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-save"></i> Simpan</button><?php if($id):?><a class="btn btn-secondary" href="<?=BASE_URL?>perpustakaan/kategori.php">Batal</a><?php endif;?></div></form></div><?php endif;?><div class="form-card"><div class="table-responsive"><table class="data-table"><thead><tr><th>Kode</th><th>Nama</th><th>Status</th><th>Keterangan</th><?php if($manage):?><th>Aksi</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['kode'])?></td><td><strong><?=e($r['nama'])?></strong></td><td><?= $r['aktif']?'<span class="badge bg-success">Aktif</span>':'<span class="badge bg-secondary">Nonaktif</span>' ?></td><td><?=e($r['keterangan']??'-')?></td><?php if($manage):?><td><a class="btn btn-sm btn-primary" href="?id=<?=$r['id']?>"><i class="bi bi-pencil-square"></i></a><form method="post" class="d-inline" onsubmit="return confirm('Hapus kategori ini?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-danger" title="Hapus kategori" aria-label="Hapus kategori"><i class="bi bi-trash"></i></button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';
